"""Offline schema checks for fixtures/kalshi_series_catalog.json (regenerated by
scripts/fetch_series_catalog.py, which needs the network and never runs here)."""

from __future__ import annotations

import json
import re
from datetime import date, datetime

import pytest

from app import config

PATH = config.FIXTURES_DIR / "kalshi_series_catalog.json"

# Every catalog event the research contract (section B) lists, plus the ones the research found real.
CONTRACT_EVENT_IDS = {
    "rain", "rain_5mm", "hot_80", "hot_85", "hot_90", "cold_40", "snow", "home_game", "home_win",
    "playoff_home", "away_playoff", "weekend_rain",
    "dc_shutdown", "tx_heat_austin", "tx_heat_houston", "tx_heat_dallas", "tx_heat_san_antonio", "gas_price",
}
# Events the contract says have no contract: they must carry null + a reason.
NO_CONTRACT = {"rain_5mm", "home_game", "weekend_rain"}

EVENT_KEYS = {
    "id", "aliases", "family", "label", "event_definition", "kalshi_series", "primary_title", "null_reason",
    "settlement_station", "strike_semantics", "cadence", "buy_ahead", "basis_note", "open_now", "instruments",
}
INSTRUMENT_KEYS = {
    "series", "role", "filter", "strike", "exists", "title", "api_frequency", "settlement_sources", "contract_url",
    "rules_primary", "strike_types", "open_now", "n_open_markets", "n_settled_markets_seen", "first_close",
    "last_close", "median_volume_per_event", "median_volume_per_market", "median_lead_hours", "rule_source_history",
}
SERIES_RE = re.compile(r"^KX[A-Z0-9]+$")


@pytest.fixture(scope="module")
def catalog() -> dict:
    return json.loads(PATH.read_text())


@pytest.fixture(scope="module")
def events(catalog) -> dict[str, dict]:
    return {e["id"]: e for e in catalog["events"]}


def _iso_date(s):
    return s is None or isinstance(date.fromisoformat(s), date)


def test_top_level(catalog):
    assert catalog["api_base"] == "https://api.elections.kalshi.com/trade-api/v2"
    datetime.fromisoformat(catalog["generated_at"])
    assert isinstance(catalog["notes"], list) and isinstance(catalog["events"], list)


def test_every_contract_event_has_an_entry(events):
    known = set(events) | {a for e in events.values() for a in e["aliases"]}
    assert CONTRACT_EVENT_IDS <= known, CONTRACT_EVENT_IDS - known


def test_ids_and_aliases_unique(catalog):
    names = [e["id"] for e in catalog["events"]] + [a for e in catalog["events"] for a in e["aliases"]]
    assert len(names) == len(set(names))


def test_event_schema(events):
    for eid, e in events.items():
        assert EVENT_KEYS <= set(e), (eid, EVENT_KEYS - set(e))
        assert e["family"] in {"weather", "sports", "calendar"}, eid
        for k in ("label", "event_definition", "settlement_station", "strike_semantics", "cadence", "buy_ahead",
                  "basis_note"):
            assert isinstance(e[k], str) and e[k].strip(), (eid, k)
        assert isinstance(e["open_now"], bool), eid
        assert isinstance(e["instruments"], list), eid


def test_null_series_carry_a_reason(events):
    for eid, e in events.items():
        if e["kalshi_series"] is None:
            assert e["null_reason"] and e["null_reason"].startswith("no_contract"), eid
            assert e["open_now"] is False
        else:
            assert e["null_reason"] is None, eid
            assert e["kalshi_series"] and all(SERIES_RE.match(s) for s in e["kalshi_series"]), eid
    for eid in NO_CONTRACT:
        assert events[eid]["kalshi_series"] is None, eid


def test_kalshi_series_are_existing_primary_instruments(events):
    for eid, e in events.items():
        primary = [i["series"] for i in e["instruments"] if i["role"] == "primary" and i["exists"]]
        assert (e["kalshi_series"] or []) == primary, eid
        if e["kalshi_series"]:
            assert e["primary_title"] == next(i["title"] for i in e["instruments"] if i["series"] == primary[0])
            assert e["open_now"] == any(i["open_now"] for i in e["instruments"] if i["role"] == "primary")


def test_instrument_schema(events):
    for eid, e in events.items():
        for i in e["instruments"]:
            where = (eid, i.get("series"))
            assert INSTRUMENT_KEYS <= set(i), (where, INSTRUMENT_KEYS - set(i))
            assert "_markets" not in i, where
            assert SERIES_RE.match(i["series"]), where
            assert i["role"] in {"primary", "alternative", "legacy"}, where
            assert i["exists"] is True, where
            assert i["title"] and i["settlement_sources"], where
            assert all(s["name"] for s in i["settlement_sources"]), where
            assert isinstance(i["open_now"], bool) and i["open_now"] == (i["n_open_markets"] > 0), where
            for k in ("first_close", "last_close"):
                assert _iso_date(i[k]), where
            if i["n_settled_markets_seen"] or i["n_open_markets"]:
                assert i["rules_primary"], where
            if i["role"] == "legacy":
                assert not i["open_now"], where
            for span in i["rule_source_history"]:
                assert span["first"] <= span["last"] and span["n_markets"] > 0, where


def test_weather_strikes_are_strict_and_measured(events):
    for eid in ("hot_80", "hot_85", "hot_90", "cold_40", "tx_heat_austin", "tx_heat_houston", "tx_heat_dallas",
                "tx_heat_san_antonio"):
        e = events[eid]
        assert "strict" in e["strike_semantics"], eid
        inst = e["instruments"][0]
        sa = inst["strike_availability"]
        assert sa["days_checked"] > 0, eid
        assert 0 <= sa["days_exact_strike_listed"] <= sa["days_checked"], eid
        assert sa["event_days_with_exact_strike"] <= sa["event_days_with_strike_within_1F"] <= sa["event_days"], eid
        assert str(inst["threshold"]) in sa["condition"], eid


def test_rain_points_at_the_live_series(events):
    rain = events["rain"]
    assert rain["kalshi_series"] == ["KXRAIN"]
    live = next(i for i in rain["instruments"] if i["series"] == "KXRAIN")
    assert live["filter"] == "-NYC" and "strictly greater than 0" in live["rules_primary"]
    legacy = next(i for i in rain["instruments"] if i["series"] == "KXRAINNYC")
    assert legacy["role"] == "legacy" and not legacy["open_now"]


def test_playoff_series_lead_days(events):
    for eid in ("playoff_home", "away_playoff"):
        for i in events[eid]["instruments"]:
            if i["series"] in ("KXNBASERIES", "KXNHLSERIES"):
                lead = i["series_lead_days"]
                assert lead["n_with_game1"] > 0 and lead["range"][0] >= 0, (eid, i["series"])
